function palletTypeRules(type){
  const normalized=type==='2-way-block'||type==='4-way-block'?'block':type;
  const builtIn={
    '2-way-runner':{label:'2-Way Runner',maxHeight:20,canRotate:false,base:'runner',entry:'2-way',notched:false},
    '4-way-runner':{label:'4-Way Runner',maxHeight:20,canRotate:true,base:'runner',entry:'4-way',notched:true},
    'block':{label:'Block',maxHeight:16,canRotate:true,base:'block',entry:'4-way',notched:false},
    '2-way-crate':{label:'2-Way Crate',maxHeight:1,canRotate:false,base:'crate',entry:'2-way',notched:false},
    '4-way-crate':{label:'4-Way Crate',maxHeight:1,canRotate:true,base:'crate',entry:'4-way',notched:true}
  };
  if(builtIn[normalized])return builtIn[normalized];
  const custom=(state?.settings?.customProductTypes||[]).find(x=>x.id===normalized);
  if(custom)return {label:custom.label,maxHeight:Number(custom.maxHeight)||20,canRotate:Boolean(custom.canRotate),base:['runner','block','crate'].includes(custom.base)?custom.base:'runner',entry:custom.entry==='2-way'?'2-way':'4-way',notched:Boolean(custom.notched),defaults:custom.defaults||null,id:custom.id};
  return {label:normalized||'4-Way Runner',maxHeight:20,canRotate:true,base:'runner',entry:'4-way',notched:true}
}
