  const custom=(state.settings.customProductTypes||[]).map(t=>`<option value="${t.id}" ${selected===t.id?'selected':''}>${String(t.label).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</option>`).join('');
