    for(const b of blocks)if(Number(b.qty)>0)out.push({label:`Blocks ${b.family} × ${b.length} in · ${wayLabel(type.entry)}`,family:b.family||'4x4',materialType:'Madera',count:qty*Number(b.qty),cutLength:Number(b.length)||4,grade:normalizeQualityValue(b.grade,1),way:normalizedWay(type.entry),allow});
