    if(fields.includes('length'))inputs.push(`<label><span>Largo</span><input id="amLength" type="number" min="0.001" step="0.001" value="48"></label>`);
    if(fields.includes('weight'))inputs.push(`<label><span>Peso (${def.defaultUnit||'lb'})</span><input id="amWeight" type="number" min="0.01" step="0.01" value="0"></label>`);
