    if(fields.includes('unit'))inputs.push(`<label><span>Unidad</span><select id="amGenericUnit">${productDefinitionUnitOptions(def.defaultUnit)}</select></label>`);
    openDialog('Agregar producto al inventario',`${def.name} · ${productDefinitionSchemaLabel(def.schema,fields)}`,`<div class="form-grid"><label class="wide"><span>Tipo de producto / material</span><div class="customer-picker-row"><select id="amProductType" data-search-select data-search-placeholder="Buscar producto…">${additionalProductTypeOptions(selected)}</select><button class="btn secondary" id="amDefineType">+ Definir tipo</button></div></label>${inputs.join('')}<label><span>${fields.includes('weight')&&!fields.includes('quantity')?'Existencia disponible ('+(def.defaultUnit||'lb')+')':'Cantidad inicial'}</span><input id="amQty" type="number" min="0" step="0.01" value="0"></label><label><span>Costo por unidad ($)</span><input id="amUnitCost" type="number" min="0" step="0.01" value="0"></label><label><span>Mínimo</span><input id="amMin" type="number" min="0" step="0.01" value="0"></label></div><div class="notification info">Inventario usa exactamente los mismos campos definidos para este producto. Así una orden pendiente puede reconocerlo automáticamente.</div><div class="dialog-actions"><button class="btn secondary" id="amCancel">Cancelar</button><button class="btn" id="amSave">Agregar al inventario</button></div>`);
    document.getElementById('amCancel').onclick=closeDialog;
