function updateConversionPreview(){const src=lumberById(document.getElementById('convSource')?.value),qty=Math.max(1,Math.floor(Number(document.getElementById('convQty')?.value)||1)),yieldPer=Math.max(1,Math.floor(Number(document.getElementById('convYield')?.value)||1)),op=document.getElementById('convOperation')?.value||'length',box=document.getElementById('convPreview');if(!box)return;if(!src){box.className='notification danger';box.innerHTML='Selecciona una pieza fuente.';return}if(op==='length'){const cuts=readCutPattern(),sourceLength=sourceLengthIn(src),used=cuts.reduce((a,c)=>a+c.lengthIn*c.qty,0);if(src.category==='range'){if(!cuts.length){box.className='notification danger';box.innerHTML='Agrega un largo destino.';return}if(cuts.length!==1||Number(cuts[0].qty)!==1){box.className='notification danger';box.innerHTML='Para material reciclado por rango, procesa una medida final por cada pieza fuente.';return}if(Number(cuts[0].lengthIn)>Number(src.maxLengthIn)){box.className='notification danger';box.innerHTML=`El largo destino no puede superar ${src.maxLengthIn} in.`;return}box.className='notification info';box.innerHTML=`<b>Procesar reciclado por rango:</b> ${qty} pieza${qty===1?'':'s'} de ${src.size} → <b>${qty}</b> pieza${qty===1?'':'s'} de <b>${src.family.replace('x','×')} × ${cuts[0].lengthIn} in</b>. No se calcula desperdicio porque el largo exacto de cada pieza del rango es variable.`;return}const waste=Math.max(0,sourceLength-used),wasteTotal=waste*qty;if(!cuts.length){box.className='notification danger';box.innerHTML='Agrega al menos un corte válido.';return}if(used>sourceLength+0.001){box.className='notification danger';box.innerHTML=`El patrón usa <b>${used} in</b>, pero la pieza fuente solo tiene <b>${sourceLength} in</b>.`;return}const produced=cuts.reduce((a,c)=>a+c.qty,0)*qty;box.className=waste>0?'notification warn':'notification info';box.innerHTML=`<b>Corte de largo:</b> por cada fuente: ${cutPatternSummary(cuts)} = <b>${used} in usados</b>. Sobrante: <b>${Number(waste.toFixed(3))} in</b> por pieza. Con ${qty} fuente${qty===1?'':'s'} se crearán <b>${produced}</b> piezas y se registrarán <b>${Number(wasteTotal.toFixed(3))} in</b> de desperdicio total.`;return}if(op==='way'){const targetWay=normalizedWay(document.getElementById('convTargetWay')?.value);if(src.category!=='finished'){box.className='notification danger';box.innerHTML='Para convertir a 2-Way / 4-Way primero la pieza debe estar cortada a su largo final.';return}if(!targetWay){box.className='notification danger';box.innerHTML='Selecciona 2-Way o 4-Way.';return}if(normalizedWay(src.way)===targetWay){box.className='notification danger';box.innerHTML=`Esta pieza ya está clasificada como ${wayLabel(targetWay)}.`;return}box.className='notification info';box.innerHTML=`<b>Conversión estructural:</b> ${qty} pieza${qty===1?'':'s'} de <b>${inventoryMaterialLabel(src)}</b> → <b>${src.family.replace('x','×')}×${Number(src.pieceLengthIn)} · ${wayLabel(targetWay)}</b>. Se conserva material y calidad; para 4-Way se registra el proceso de notch.`;return}if(src.category==='range'){box.className='notification danger';box.innerHTML='El material reciclado por rango primero debe procesarse con Cortar largo para definir una medida final.';return}const target=selectedConversionTarget();if(!target){box.className='notification danger';box.innerHTML='Indica la medida destino.';return}if(!sectionFitsInside(src.family,target)){box.className='notification danger';box.innerHTML=`La medida <b>${target.replace('x','×')}</b> debe ser inferior y caber dentro de <b>${src.family.replace('x','×')}</b>.`;return}const produced=qty*yieldPer,lengthLabel=src.category==='raw'?`${Number(src.lengthFt)} ft`:`${Number(src.pieceLengthIn)} in`;box.className='notification info';box.innerHTML=`<b>Conversión de sección:</b> ${qty} pieza${qty===1?'':'s'} de ${src.family.replace('x','×')} → <b>${produced}</b> pieza${produced===1?'':'s'} de <b>${target.replace('x','×')} × ${lengthLabel}</b> · calidad #${src.grade}. El rendimiento de <b>${yieldPer}</b> por fuente es el que tú indicaste.`}
