function openOrderSpecification(id){const o=orderById(id);if(!o){toast('No encontré esa orden.');return}try{const products=orderProducts(o),direct=orderInventoryItems(o);const inventoryBody=direct.map(x=>{const s=x.procurement==='described'?describedAdditionalInventoryStatus(x):null,currentCost=x.procurement==='described'?additionalItemCurrentUnitCost(x):Math.max(0,Number(x.unitCostSnapshot)||0);return `<section class="spec-product"><div class="section-head"><div><h3>${x.label}</h3><p>${x.qty} ${x.unit||'unidades'} · ${x.procurement==='described'?'producto descrito':'producto del inventario'}${x.qcRequired?' · QC':''}${x.htRequired?' · HT':''}</p></div><span class="pill ${x.procurement==='described'?(s.ready?'green':'yellow'):'blue'}">${x.procurement==='described'?(s.ready?'Material listo':'Pendiente'):'Inventario'}</span></div><div class="detail-grid"><div class="detail"><b>Detalle</b>${x.detail||'—'}</div><div class="detail"><b>Calidad</b>${x.grade!==''?qualityLabel(x.grade):'—'}</div><div class="detail"><b>Inventario compatible</b>${x.procurement==='described'?`${s.available} disponibles · ${s.missing} faltantes`:'Seleccionado directamente'}</div><div class="detail"><b>Costo registrado</b>${currentCost?money(currentCost):'Pendiente'} / ${x.unit||'unidad'}</div><div class="detail"><b>Precio de venta</b>${money(x.salePrice||0)} / ${x.unit||'unidad'}</div><div class="detail"><b>Valor de línea</b>${money((Number(x.qty)||0)*(Number(x.salePrice)||0))}</div></div>${x.itemNote?`<div class="notification info item-instruction"><b>Nota de este producto</b><div>${x.itemNote}</div></div>`:''}</section>`}).join('');const body=products.map((p,i)=>{const title=p.productName||p.templateName||p.name||`${p.length}×${p.width}`,cond=palletConditionLabel(p.condition||'new');if(!conditionUsesBuildSpec(p.condition||'new'))return `<section class="spec-product"><div class="section-head"><div><h3>${title}</h3><p>${p.qty} pallets · ${cond}</p></div><span class="pill green">${cond}</span></div><div class="notification info"><b>Especificación simplificada</b><div class="small">Esta condición no requiere tablas, runners ni plano de fabricación desde la orden.${conditionIsFixed4840(p.condition)?' Se maneja como 48×40 4-Way y puede girarse.':''}</div></div>${p.itemNote?`<div class="notification info item-instruction"><b>Nota de esta medida</b><div>${p.itemNote}</div></div>`:''}</section>`;return `<section class="spec-product"><div class="section-head"><div><h3>${title}</h3><p>${p.qty} pallets · ${palletTypeRules(p.type).label}${p.qcRequired?' · QC':''}${p.htRequired?' · HT':''}</p></div>${p.condition==='combo'?`<span class="pill yellow">Combo · calidad por definir</span>`:`<span class="pill green">Calidad ${productGradeSummary(p)}</span>`}</div><div class="pallet-preview-grid technical-pair"><div><h4>Vista frontal</h4>${technicalElevationSvg(p,'front')}</div><div><h4>Vista lateral (costado)</h4>${technicalElevationSvg(p,'side')}</div></div><div class="pallet-preview-grid"><div><h4>Vista superior</h4>${palletDrawingSvg(p,'top')}</div><div><h4>Vista inferior</h4>${palletDrawingSvg(p,'bottom')}</div></div>${productSpecNote(p)}${p.itemNote?`<div class="notification info item-instruction"><b>Nota de esta medida</b><div>${p.itemNote}</div></div>`:''}</section>`}).join('')+inventoryBody||'<div class="empty-state">Esta orden no tiene especificación técnica guardada.</div>';openFullDialog(`Especificación · Orden #${o.id}`,`${o.customer}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}`,`${(o.deliveryTimeFrom||o.deliveryTimeTo||o.deliveryTime)?`<div class="notification info"><b>Horario de recepción del cliente</b><div class="small">${o.deliveryTimeFrom&&o.deliveryTimeTo?`${o.deliveryTimeFrom} – ${o.deliveryTimeTo}`:(o.deliveryTime||o.deliveryTimeFrom||o.deliveryTimeTo)}</div></div>`:''}${body}<div class="dialog-actions"><button type="button" class="btn secondary" id="specClose">Cerrar</button><button type="button" class="btn" id="specPrint">Imprimir hoja de fabricación</button></div>`);document.getElementById('specClose').onclick=closeDialog;document.getElementById('specPrint').onclick=()=>window.print()}catch(err){console.error(err);toast('No se pudo abrir el gráfico. Revisa la especificación de esta orden.')}}

function reserveFinishedPiecesForOrder(order){
  const reqs=finishedPieceRequirements({products:orderProducts(order)}),reservation={};
  for(const req of reqs){let remain=req.count;const matches=(state.lumber||[]).filter(x=>x.category==='finished'&&materialTypeOf(x).toLowerCase()===String(req.materialType||'Madera').toLowerCase()&&canonicalBoardFamily(x.family)===canonicalBoardFamily(req.family)&&Math.abs(Number(x.pieceLengthIn)-Number(req.length))<0.001&&sameQuality(x.grade,req.grade)&&(x.origin==='recycled'?'recycled':'new')===(req.origin==='recycled'?'recycled':'new')&&normalizedWay(x.way)===normalizedWay(req.way)&&availableOf(x)>0).sort((a,b)=>availableOf(b)-availableOf(a));for(const x of matches){if(remain<=0)break;const n=Math.min(remain,availableOf(x));reservation[x.id]=(reservation[x.id]||0)+n;remain-=n}if(remain>0)return false}
  for(const [id,n] of Object.entries(reservation)){const x=lumberById(id);x.reserved=(Number(x.reserved)||0)+n}
  order.materialReservation=reservation;order.requiredPieces=reqs;save();return true
}
function consumeFinishedReservation(order){for(const [id,n] of Object.entries(order.materialReservation||{})){const x=lumberById(id);if(!x)continue;x.qty=Math.max(0,(Number(x.qty)||0)-n);x.reserved=Math.max(0,(Number(x.reserved)||0)-n)}order.materialReservation={};save()}
function startCut(id){const o=orderById(id);if(!o)return;const rows=pieceAvailability({products:orderProducts(o)}),missing=rows.filter(r=>r.missing>0);if(missing.length){toast(`${pieceSizeLabel(missing[0])}: faltan ${missing[0].missing} piezas.`);render();return}if(!reserveFinishedPiecesForOrder(o)){toast('El inventario cambió y ya no alcanza para reservar todas las piezas.');render();return}o.stage='cutting';addNote(`Orden #${o.id}: piezas terminadas reservadas para producción.`);save();toast('Piezas listas reservadas.');render()}
function finishCut(id){const o=orderById(id);if(!o)return;consumeFinishedReservation(o);o.stage='material_ready';addNote(`Orden #${o.id}: piezas listas entregadas a fabricación.`);save();toast('Piezas listas → apareció en Fabricación.');render()}
function startBuild(id){const o=orderById(id);o.stage='building';addNote(`Orden #${o.id}: fabricación iniciada.`);save();toast('Fabricación iniciada.');render()}
function consumeComboMaterialAtReady(order,mode){const comboProducts=orderProducts(order).filter(p=>p.condition==='combo');if(!comboProducts.length)return true;for(const p of comboProducts)p.resolvedComboMode=mode;const reqs=finishedPieceRequirements({products:comboProducts});const reservation={};for(const req of reqs){let remain=req.count;const matches=(state.lumber||[]).filter(x=>x.category==='finished'&&canonicalBoardFamily(x.family)===canonicalBoardFamily(req.family)&&Number(x.pieceLengthIn)===Number(req.length)&&Number(x.grade)===Number(req.grade)&&(x.origin==='recycled'?'recycled':'new')===(req.origin==='recycled'?'recycled':'new')&&availableOf(x)>0).sort((a,b)=>availableOf(b)-availableOf(a));for(const x of matches){if(remain<=0)break;const n=Math.min(remain,availableOf(x));reservation[x.id]=(reservation[x.id]||0)+n;remain-=n}if(remain>0){for(const p of comboProducts)delete p.resolvedComboMode;toast(`${pieceSizeLabel(req)}: faltan ${remain} piezas para registrar el Combo.`);return false}}for(const [id,n] of Object.entries(reservation)){const x=lumberById(id);x.qty=Math.max(0,(Number(x.qty)||0)-n)}order.comboMaterialResolvedAt=new Date().toISOString();order.comboMaterialMode=mode;return true}
function finishBuildDialog(id){const o=orderById(id);if(!o)return;const buildProducts=orderProducts(o),hasCombo=buildProducts.some(p=>p.condition==='combo'),configuredCosts=[...new Set(buildProducts.map(p=>Number(p.fabricationCost)||0))],defaultLabor=configuredCosts.length===1?configuredCosts[0]:0;openDialog(`Terminar fabricación #${o.id}`,`${o.customer} · ${o.qty} pallets`,`<div class="form-grid"><label><span>Quién fabricó / responsable</span><select id="fbWorker"><option value="">— Seleccionar —</option>${activeWorkers().map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></label><label><span>Costo de fabricación por pallet ($)</span><input id="fbLabor" type="number" min="0" step="0.01" value="${defaultLabor}"></label>${hasCombo?`<label class="wide"><span>Material usado en pallets Combo</span><select id="fbComboMode"><option value="">— Seleccionar material usado —</option><option value="runner_new">Runner nuevo + tablas recicladas</option><option value="board_new">Tablas nuevas + runners reciclados</option></select></label>`:''}</div>${hasCombo?`<div class="notification warn"><b>Combo:</b> el inventario no se descontó antes. Al marcar Ready to Dispatch se descontará ahora según el material realmente utilizado.</div>`:`<div class="notification info">El costo de material se toma del costo registrado al comprar la madera y se conserva a través de los cortes/conversiones disponibles.</div>`}<div class="dialog-actions"><button class="btn secondary" id="fbCancel">Cancelar</button><button class="btn" id="fbSave">Terminar y liberar</button></div>`);document.getElementById('fbCancel').onclick=closeDialog;document.getElementById('fbSave').onclick=()=>{const workerId=document.getElementById('fbWorker').value,laborUnitCost=Math.max(0,Number(document.getElementById('fbLabor').value)||0);if(!workerId){toast('Selecciona quién fabricó la orden.');return}if(hasCombo){const mode=document.getElementById('fbComboMode').value;if(!mode){toast('Selecciona qué material se usó en los pallets Combo.');return}if(!consumeComboMaterialAtReady(o,mode))return}finishBuild(id,workerId,laborUnitCost);closeDialog()}}
function finishBuild(id,workerId='',laborUnitCost=0){const o=orderById(id);if(!o)return;o.stage='ready_load';const products=orderProducts(o),builtAt=new Date().toISOString();let materialTotal=0,laborTotal=0;for(const p of products){const materialCost=productMaterialCost(p),configuredLabor=Number(p.fabricationCost),effectiveLaborUnit=Number.isFinite(configuredLabor)&&configuredLabor>=0?configuredLabor:Number(laborUnitCost||0),laborCost=(Number(p.qty)||0)*effectiveLaborUnit,totalCost=materialCost+laborCost;p.costSummary={workerId,laborUnitCost:effectiveLaborUnit,materialCost,laborCost,totalCost,builtAt};materialTotal+=materialCost;laborTotal+=laborCost;const sku=p.productName||p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty+=(Number(p.qty)||0);f.reserved+=(Number(p.qty)||0)}if(!products.length){const f=findFinished(o.palletSku);f.qty+=o.qty;f.reserved+=o.qty;laborTotal=o.qty*Number(laborUnitCost||0)}o.manufacturingCost={workerId,laborUnitCost:Number(laborUnitCost)||0,materialCost:materialTotal,laborCost:laborTotal,totalCost:materialTotal+laborTotal,builtAt};state.fabricationLog=Array.isArray(state.fabricationLog)?state.fabricationLog:[];state.fabricationLog.push({id:'FAB-'+Date.now(),orderId:o.id,createdAt:builtAt,workerId,qty:o.qty,materialCost:materialTotal,laborCost:laborTotal,totalCost:materialTotal+laborTotal});addNote(`Orden #${o.id}: ${o.qty} pallets terminados. Costo total ${money(materialTotal+laborTotal)}.`);save();toast('Fabricación terminada → orden enviada a Carga.');render()}
function openLoadOrder(id){const o=orderById(id);const pickup=o.shipping==='pickup';openDialog(`Pedido #${o.id}`,`${o.customer}${o.clientOrder?` · Cliente ${o.clientOrder}`:''} · ${pickup?'Recogida del cliente':'Envío de fábrica'}`,`${orderRequirementHtml(o)}${o.trailerReturn&&o.trailerReturn!=='unknown'?`<div class="notification info"><b>Retorno de tráiler:</b> ${trailerReturnLabel(o.trailerReturn)}${o.trailerReturnNote?` · ${o.trailerReturnNote}`:''}</div>`:''}<div class="workflow"><span class="step active">1 Verificar</span><span class="step">2 Optimizar / cargar</span><span class="step">3 Evidencia</span><span class="step">4 Firma</span><span class="step">5 Cerrar</span></div><div class="detail-grid"><div class="detail"><b>Producto</b>${o.product}</div><div class="detail"><b>Cantidad</b>${o.qty} pallets</div><div class="detail"><b>Transporte</b>${pickup?'Cliente trae tráiler':'Fábrica pone chofer y tráiler'}</div><div class="detail"><b>Estado</b>${stageLabel(o.stage)}</div></div><div class="stage-actions"><button type="button" class="btn secondary" id="orderLM">Preparar / optimizar carga</button><button type="button" class="btn" id="markLoading">Marcar cargando</button></div><div class="section evidence"><b>Foto / factura firmada</b><p class="small">La foto es opcional, pero se conserva porque normalmente sirve como evidencia de la factura firmada.</p><input id="evidenceFile" type="file" accept="image/*"><div class="evidence-preview" id="evidencePreview">Sin foto seleccionada.</div></div><div class="section form-grid"><label class="wide"><span>Firma / nombre de quien recibe</span><input id="signatureName" placeholder="Nombre o firma registrada"></label><label class="wide"><span>Notas de carga</span><textarea id="loadNotes">${o.notes||''}</textarea></label></div><div class="dialog-actions"><button type="button" class="btn secondary" id="loadCancel">Cerrar</button><button type="button" class="btn" id="finishDispatch">${pickup?'Completar recogida':'Despachar / en tránsito'}</button></div>`);
  document.getElementById('loadCancel').onclick=closeDialog;document.getElementById('orderLM').onclick=()=>openLoadPreparation(o.id);document.getElementById('markLoading').onclick=()=>{o.stage='loading';save();toast('Pedido marcado como cargando.');};document.getElementById('evidenceFile').onchange=e=>{document.getElementById('evidencePreview').textContent=e.target.files[0]?`Foto seleccionada: ${e.target.files[0].name}`:'Sin foto seleccionada.'};document.getElementById('finishDispatch').onclick=()=>{const sig=document.getElementById('signatureName').value.trim();const hasPhoto=Boolean(document.getElementById('evidenceFile').files[0]);o.notes=document.getElementById('loadNotes').value;if(pickup){completeOrder(o,`${sig?'Firma':'Sin firma'}${hasPhoto?' + foto factura':''}`)}else{o.stage='transit';o.evidence=`${sig?'Firma salida':'Sin firma salida'}${hasPhoto?' + foto':''}`;addNote(`Orden #${o.id}: salió de fábrica y está en tránsito.`);save();closeDialog();toast('Pedido en tránsito.');render()}}
}
function completeDelivery(id){const o=orderById(id);completeOrder(o,(o.evidence||'Salida registrada')+' + entrega confirmada')}
function completeOrder(o,evidence){const products=orderProducts(o),direct=orderInventoryItems(o);if(products.length){for(const p of products){const sku=p.productName||p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty=Math.max(0,f.qty-(Number(p.qty)||0));f.reserved=Math.max(0,f.reserved-(Number(p.qty)||0))}}else if(!direct.length&&o.palletSku){const f=findFinished(o.palletSku);f.qty=Math.max(0,f.qty-o.qty);f.reserved=Math.max(0,f.reserved-o.qty)}if(direct.length)consumeAdditionalStockItems(o);const histProducts=clone(products),histInventoryItems=clone(direct);const palletSales=histProducts.reduce((a,p)=>a+(Number(p.qty)||0)*(Number(p.salePrice)||0),0),directSales=additionalItemsValue(histInventoryItems),salesTotal=palletSales+directSales,palletCost=histProducts.reduce((a,p)=>a+(Number(p.costSummary?.totalCost)||0),0),directCost=additionalItemsCost(histInventoryItems),costTotal=palletCost+directCost,profitTotal=salesTotal-costTotal;state.history.unshift({id:o.id,clientOrder:o.clientOrder||'',customer:o.customer,shipping:o.shipping,completed:new Date().toLocaleString('es-US'),evidence:evidence||'Registro completado',products:histProducts,inventoryItems:histInventoryItems,costTotal,salesTotal,profitTotal,manufacturingCost:clone(o.manufacturingCost||{}),qcRequired:Boolean(o.qcRequired),qcCompletedAt:o.qcCompletedAt||'',htRequired:Boolean(o.htRequired),trailerReturn:o.trailerReturn||'unknown',trailerReturnNote:o.trailerReturnNote||''});state.orders=state.orders.filter(x=>x.id!==o.id);addNote(`Orden #${o.id}: completada y enviada al historial.`);save();closeDialog();toast('Orden completada → Historial.');render()}
function openLoadPreparation(id){
  const o=orderById(id);if(!o)return;const items=loadItemsFor(o);if(!items.length){toast(orderInventoryItems(o).length?'Esta orden contiene productos de inventario directo. Todavía no requieren acomodo de pallets en LoadMaster.':'Esta orden no tiene medidas válidas para LoadMaster.');return}
  const rows=items.map((x,i)=>`<tr data-prep-row="${i}"><td><b>${x.name||`${x.length}×${x.width}`}</b><div class="small">${palletTypeRules(x.type).label}</div></td><td><input class="qty-locked" type="number" value="${Number(x.quantity)||1}" readonly></td><td><input data-prep-height type="number" min="1" value="${Math.max(1,Number(x.maxHeight)||palletTypeRules(x.type).maxHeight)}"></td><td><b>${palletTypeRules(x.type).canRotate?'Sí':'No'}</b><div class="small">Automático por tipo</div></td></tr>`).join('');
  openDialog(`Preparar carga #${o.id}`,`${o.customer} · ${loadTotal(items)} pallets`,`<div class="notification info"><b>Datos conectados.</b> Cantidad, tipo y giro vienen de la orden. Aquí solo ajustas la altura máxima si esta carga necesita una excepción.</div><div class="prep-trailer"><label><span>Ancho tráiler (in)</span><input id="prepTrailerWidth" type="number" value="${Number(o.trailerWidth)||96}"></label><label><span>Largo tráiler (in)</span><input id="prepTrailerLength" type="number" value="${Number(o.trailerLength)||628}"></label></div><div class="table-wrap prep-table"><table><thead><tr><th>Medida / tipo</th><th>Cantidad</th><th>Máximo por pila</th><th>Giro</th></tr></thead><tbody>${rows}</tbody></table></div><div class="dialog-actions"><button class="btn secondary" id="prepCancel">Volver</button><button class="btn" id="prepLaunch">Abrir LoadMaster a pantalla completa</button></div>`);
  document.getElementById('prepCancel').onclick=()=>{closeDialog();openLoadOrder(id)};document.getElementById('prepLaunch').onclick=()=>{const prepared=items.map((item,i)=>{const row=document.querySelector(`[data-prep-row="${i}"]`),rules=palletTypeRules(item.type);return {...item,quantity:Number(item.quantity)||1,maxHeight:Math.max(1,Number(row.querySelector('[data-prep-height]').value)||rules.maxHeight),canRotate:rules.canRotate,type:item.type}});o.loadItems=clone(prepared);o.trailerWidth=Math.max(1,Number(document.getElementById('prepTrailerWidth').value)||96);o.trailerLength=Math.max(1,Number(document.getElementById('prepTrailerLength').value)||628);save();localStorage.setItem('loadmaster-theme',state.settings.theme||'system');localStorage.setItem(LM_HANDOFF,JSON.stringify({version:2,source:'Pallet Operations',orderId:o.id,customer:o.customer,shipping:o.shipping,trailer:{width:o.trailerWidth,length:o.trailerLength},items:prepared,returnUrl:'index.html#carga',createdAt:new Date().toISOString()}));window.location.href=`loadmaster.html?platform=1&order=${encodeURIComponent(o.id)}`}
}
